def bubble_sort(arr):
n = len(arr)
for i in range(n):
    for j in range(0, n - 1):
        if arr[j] > arr[j + 1]:
            arr[j], arr[j + 1] = arr[j + 1], arr[j]
return arr

from flask import Flask, request, jsonify

app = Flask(__name__)
users_db = {}

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    if user_id not in users_db:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(users_db[user_id]), 200

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Missing name field'}), 400
    user_id = len(users_db) + 1
    users_db[user_id] = {'id': user_id, 'name': data['name']}
    return jsonify(users_db[user_id]), 201

if __name__ == '__main__':
    app.run(debug=False)

class BankAccount:
    '''Represents a simple bank account with basic operations'''

    def __init__(self, account_holder, initial_balance=0):
        self.account_holder = account_holder
        self._balance = max(0, initial_balance)
        self._transactions = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self._balance += amount
        self._transactions.append(('deposit', amount))
        return self._balance

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self._balance:
            raise ValueError("Insufficient funds")
        self._balance -= amount
        self._transactions.append(('withdrawal', amount))
        return self._balance

    def get_balance(self):
        return self._balance

    def get_statement(self):
        return [f"{action}: ${amt:.2f}" for action, amt in self._transactions]
